@classmethod
def discover_tests(
    cls,
    test_dirs: list[str],
    excluded_patterns: list[str],
    root_dir: Path | str = "."
) -> tuple[list[TestSymbol], list[str]]:
    root = Path(root_dir).resolve()
    tests: list[TestSymbol] = []
    errors: list[str] = []

    normalized_exclusions = set()
    for pattern in excluded_patterns:
        if not pattern:
            continue
        norm = pattern.replace("\\", "/").strip("/")
        if norm:
            normalized_exclusions.add(norm)

    def is_excluded(rel_path: str) -> bool:
        if not normalized_exclusions:
            return False
        rel_norm = rel_path.replace("\\", "/").strip("/")
        if not rel_norm:
            return False
        parts = rel_norm.split("/")
        for ex in normalized_exclusions:
            if rel_norm == ex or rel_norm.startswith(ex + "/"):
                return True
            if ex in parts:
                return True
        return False

    for tdir in test_dirs:
        target = (root / tdir).resolve()

        try:
            target.relative_to(root)
        except ValueError:
            errors.append(f"Security Violation: Test dir '{tdir}' escapes project root '{root}'")
            continue

        if not target.exists():
            continue

        files = [target] if target.is_file() else sorted(target.rglob("*.py"))
        for f in files:
            rel = str(f.relative_to(root)).replace("\\", "/")
            if is_excluded(rel):
                continue
            t_list, errs = cls.parse_file(f, root_dir=root)
            tests.extend(t_list)
            errors.extend(errs)

    return tests, errors

